begin;
do $test$
declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();r jsonb;room uuid;fa uuid;fb uuid;fc uuid;other uuid;doc jsonb;independent jsonb;sess jsonb;before_result jsonb;entry jsonb;feed jsonb;denied boolean;
 label text:='LIB-'||upper(substr(md5(random()::text),1,10));
begin
 begin
 insert into private.faculty_approvals(email) values(a::text||'@classpulse.invalid'),(b::text||'@classpulse.invalid');
 insert into auth.users(id,email,raw_user_meta_data,is_anonymous,email_confirmed_at) values(a,a::text||'@classpulse.invalid','{"full_name":"Library A"}',false,now()),(b,b::text||'@classpulse.invalid','{"full_name":"Library B"}',false,now());
 execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'is_anonymous',false)::text,true);
 r:=public.classpulse_save_room(null,label);select id into room from public.rooms where roster_id=(r->>'id')::uuid;
 perform public.classpulse_import_roster((r->>'id')::uuid,'[{"id":"001","name":"Quiz Student","emailid":"student@classpulse.invalid"}]');
 insert into public.quiz_folders(teacher_id,name) values(a,'First') returning id into fa;
 insert into public.quiz_folders(teacher_id,name) values(a,'Second') returning id into fb;
 insert into public.quiz_folders(teacher_id,name,parent_id) values(a,'Child',fa) returning id into fc;
 doc:=public.classpulse_save_quiz(null,fc,'Original quiz','[{"type":"true_false","prompt":"Preserve this question","points":1,"options":["True","False"],"correct_position":1,"accepted_answers":[],"manual_grading":false}]',null,null);
 sess:=public.classpulse_launch_quiz(room,(doc->>'quiz_id')::uuid,(doc->>'version_id')::uuid,(doc->>'revision')::int);perform public.classpulse_start_session((sess->>'id')::uuid);
 denied:=false;begin perform public.classpulse_library_action('quiz',(doc->>'quiz_id')::uuid,'delete');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: active quiz deleted';end if;
 denied:=false;begin perform public.classpulse_library_action('folder',fa,'delete');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: active folder deleted';end if;
 execute 'reset role';execute 'set local role anon';perform set_config('request.jwt.claims','{}',true);
 entry:=public.classpulse_student_join(label,'001');feed:=public.classpulse_student_question((entry->>'token')::uuid);perform public.classpulse_submit_answer((entry->>'token')::uuid,(feed->'question'->>'id')::uuid,1,null);
 execute 'reset role';execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'is_anonymous',false)::text,true);
 perform public.classpulse_end_session((sess->>'id')::uuid);before_result:=public.classpulse_live_results((sess->>'id')::uuid);
 perform public.classpulse_library_action('quiz',(doc->>'quiz_id')::uuid,'rename','Renamed quiz',null,'Original quiz');
 doc:=public.classpulse_get_quiz((doc->>'quiz_id')::uuid);
 if doc->>'title'<>'Renamed quiz' or doc->'questions'->0->>'prompt'<>'Preserve this question' or (doc->'questions'->0->>'correct_position')::int<>1 then raise exception 'FAIL: rename lost quiz content or key';end if;
 if doc->>'version_number'<>'2' then raise exception 'FAIL: rename mutated published version';end if;
 denied:=false;begin perform public.classpulse_library_action('quiz',(doc->>'quiz_id')::uuid,'rename','Stale title',null,'Original quiz');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: stale rename';end if;
 perform public.classpulse_library_action('quiz',(doc->>'quiz_id')::uuid,'move',null,fb,'Renamed quiz');
 if (select folder_id from public.quizzes where id=(doc->>'quiz_id')::uuid)<>fb then raise exception 'FAIL: quiz move';end if;
 perform public.classpulse_library_action('folder',fc,'move',null,fb,'Child');
 if (select parent_id from public.quiz_folders where id=fc)<>fb then raise exception 'FAIL: folder move';end if;
 denied:=false;begin perform public.classpulse_library_action('folder',fb,'move',null,fc,'Second');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: folder cycle';end if;
 perform public.classpulse_library_action('folder',fb,'rename','Renamed folder',null,'Second');
 independent:=public.classpulse_save_quiz(null,fb,'Previously deleted','[]',null,null);
 perform public.classpulse_library_action('quiz',(independent->>'quiz_id')::uuid,'delete');
 perform public.classpulse_library_action('folder',fb,'delete');
 if exists(select 1 from public.quiz_folders where id in(fb,fc)) or exists(select 1 from public.quizzes where id=(doc->>'quiz_id')::uuid) then raise exception 'FAIL: deleted items visible';end if;
 if jsonb_array_length(public.classpulse_deleted_library()->'folders')<>2 or jsonb_array_length(public.classpulse_deleted_library()->'quizzes')<>2 then raise exception 'FAIL: deleted library';end if;
 denied:=false;begin perform public.classpulse_get_quiz((doc->>'quiz_id')::uuid);exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: deleted quiz opened';end if;
 denied:=false;begin perform public.classpulse_launch_quiz(room,(doc->>'quiz_id')::uuid,(doc->>'version_id')::uuid,(doc->>'revision')::int);exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: deleted quiz launched';end if;
 denied:=false;begin insert into public.quiz_folders(teacher_id,name,parent_id) values(a,'Blocked child',fb);exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: deleted parent accepts children';end if;
 denied:=false;begin perform public.classpulse_library_action('quiz',(doc->>'quiz_id')::uuid,'restore');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: restored quiz inside deleted folder';end if;
 if public.classpulse_live_results((sess->>'id')::uuid) is distinct from before_result then raise exception 'FAIL: saved answers or scores changed';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'is_anonymous',false)::text,true);
 if public.classpulse_deleted_library()<>'{"folders":[],"quizzes":[]}'::jsonb then raise exception 'FAIL: foreign deleted library';end if;
 denied:=false;begin perform public.classpulse_library_action('folder',fb,'restore');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: foreign restore';end if;
 denied:=false;begin perform public.classpulse_library_action('quiz',(doc->>'quiz_id')::uuid,'delete');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: foreign delete';end if;
 insert into public.quiz_folders(teacher_id,name) values(b,'Foreign destination') returning id into other;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'is_anonymous',false)::text,true);
 perform public.classpulse_library_action('folder',fb,'restore');
 if not exists(select 1 from public.quiz_folders where id=fc) or not exists(select 1 from public.quizzes where id=(doc->>'quiz_id')::uuid) then raise exception 'FAIL: folder contents not restored';end if;
 if exists(select 1 from public.quizzes where id=(independent->>'quiz_id')::uuid) then raise exception 'FAIL: unrelated deleted quiz restored';end if;
 denied:=false;begin perform public.classpulse_library_action('quiz',(doc->>'quiz_id')::uuid,'move',null,other);exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: foreign destination';end if;
 perform public.classpulse_library_action('quiz',(independent->>'quiz_id')::uuid,'restore');
 perform public.classpulse_library_action('quiz',(doc->>'quiz_id')::uuid,'delete');perform public.classpulse_library_action('quiz',(doc->>'quiz_id')::uuid,'restore');
 execute 'reset role';update private.faculty_approvals set enabled=false where email=a::text||'@classpulse.invalid';execute 'set local role authenticated';
 denied:=false;begin perform public.classpulse_library_action('quiz',(doc->>'quiz_id')::uuid,'delete');exception when raise_exception then denied:=true;end;if not denied then raise exception 'FAIL: revoked teacher deletes quiz';end if;
 execute 'reset role';execute 'set local role anon';perform set_config('request.jwt.claims','{}',true);
 denied:=false;begin perform public.classpulse_deleted_library();exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'FAIL: student deleted library';end if;
 denied:=false;begin perform public.classpulse_library_action('quiz',(doc->>'quiz_id')::uuid,'delete');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'FAIL: student deletes quiz';end if;
 execute 'reset role';raise exception using errcode='CP001',message='Rollback fixtures';
 exception when sqlstate 'CP001' then null;
 end;
 if exists(select 1 from auth.users where id in(a,b)) then raise exception 'FAIL: fixtures remain';end if;
end $test$;
rollback;
select 'PASS: quiz and folder rename, move, delete, restore, saved answers and teacher privacy verified; fixtures rolled back' as result;


